"""
Replaces an outer Toffoli(a,b,q) ... Toffoli(a,b,q) pair -- with an intervening block that only
uses the qubit set {a,b,q} as CONTROLS of diagonal gates (never as a target of an X-like gate) --
by V ... V^dagger, where V is the 4-T relative-phase Toffoli (Margolus gate). V differs from a true
Toffoli only by a diagonal relative phase that is a function of the computational basis state of
(a,b,q); since the sandwiched block is diagonal on {a,b,q} and never changes that basis state
(it only reads it as controls), the spurious phase picked up by V is exactly undone by V^dagger,
leaving the overall unitary identical to the original CCX/CCZ ... CCZ pair while cutting the
two 7-T Toffolis (14 T) down to two 4-T Margolus gates (8 T).
"""
from __future__ import annotations

from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

_DIAGONAL_1Q = {"z", "s", "sdg", "t", "tdg", "rz"}
_FLIP_NAMES = {"x", "y", "h", "sx", "sxdg", "swap"}


def _is_toffoli(g: Gate) -> bool:
    return g.name in ("ccx", "ccz")


def _same_triple(g1: Gate, g2: Gate) -> bool:
    if g1.name != g2.name:
        return False
    if g1.name == "ccx":
        return g1.qubits == g2.qubits
    return set(g1.qubits) == set(g2.qubits)


def _block_untouched_as_target(qset: set, block: list) -> bool:
    """True iff no gate in `block` ever uses a qubit of qset as the TARGET of a non-diagonal
    (basis-flipping) operation. Diagonal gates (ccz/cz/z/s/t/rz family) may freely touch qset
    qubits (as controls or as their own 1-qubit phase target -- a diagonal 1q gate never changes
    the computational basis value, so it's harmless even "on" the qubit)."""
    for g in block:
        touched = set(g.qubits) & qset
        if not touched:
            continue
        if g.name in _DIAGONAL_1Q:
            continue
        if g.name == "cz" or g.name == "ccz":
            continue
        if g.name == "cx":
            target = g.qubits[1]
            if target in touched:
                return False
            continue
        if g.name == "ccx":
            target = g.qubits[2]
            if target in touched:
                return False
            continue
        if g.name in _FLIP_NAMES:
            return False
        # measure/reset/unknown -> be conservative
        return False
    return True


def _relative_phase_toffoli(ctrl0: int, ctrl1: int, targ: int) -> list:
    a, b, t = ctrl0, ctrl1, targ
    return [
        Gate("h", (t,)),
        Gate("t", (a,)),
        Gate("t", (b,)),
        Gate("t", (t,)),
        Gate("cx", (b, a)),
        Gate("cx", (t, b)),
        Gate("cx", (a, t)),
        Gate("tdg", (b,)),
        Gate("cx", (a, b)),
        Gate("tdg", (a,)),
        Gate("tdg", (b,)),
        Gate("t", (t,)),
        Gate("cx", (t, b)),
        Gate("cx", (a, t)),
        Gate("cx", (b, a)),
        Gate("h", (t,)),
    ]


_INV_1Q = {"h": "h", "t": "tdg", "tdg": "t"}


def _dagger(block: list) -> list:
    out = []
    for g in reversed(block):
        if g.name == "cx":
            out.append(g)
        else:
            out.append(replace(g, name=_INV_1Q[g.name]))
    return out


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = c.gates
    N = len(gates)
    zero_init = set(c.zero_init)

    for i in range(N):
        g1 = gates[i]
        if not _is_toffoli(g1):
            continue
        qset1 = set(g1.qubits)
        pivot_candidates = [q for q in g1.qubits if q in zero_init]
        if not pivot_candidates:
            continue

        for j in range(i + 1, N):
            g2 = gates[j]
            if not _is_toffoli(g2):
                continue
            if not _same_triple(g1, g2):
                continue

            between = gates[i + 1:j]

            if not _block_untouched_as_target(qset1, between):
                continue

            for pivot in pivot_candidates:
                others = [q for q in g1.qubits if q != pivot]
                if len(others) != 2:
                    continue
                a, b = others

                v_gates = _relative_phase_toffoli(a, b, pivot)
                v_dag_gates = _dagger(v_gates)

                new_gates = list(gates[:i]) + v_gates + list(between) + v_dag_gates + list(gates[j + 1:])
                new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
                return new_c, Req(eps=0.0, ancillas=0, measure=False)

    return c, Req()

"""Generalize measurement-based AND-uncompute to mirrored compute/uncompute pairs.

Finds two identical ccz/ccx AND-computes onto the same zero-initialized ancilla `a` with
the same control set C, with no other gate touching `a` in between. The second occurrence
is logically an uncompute of the first (the ancilla is restored to a computational-basis
state before it, since the intervening gates don't touch it), so it may be replaced by:
H a; measure a -> fresh cbit; classically-controlled Z/CZ on C; reset a. This is exactly
the standard AND-uncompute trick, applied syntactically to the *second* occurrence of a
mirrored pair rather than requiring an explicit adjacent measurement.
"""
from __future__ import annotations

from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _and_key(g: Gate):
    """Normalized key for an AND-gate (ccz/ccx) identifying its control-set + target."""
    if g.name == "ccz":
        # ccz is symmetric in all three qubits; target = ancilla is whichever qubit is zero_init
        return ("ccz", frozenset(g.qubits))
    if g.name == "ccx":
        # ccx target is the last qubit; controls are the first two (order-independent)
        return ("ccx", frozenset(g.qubits[:2]), g.qubits[2])
    return None


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = c.gates
    n = len(gates)

    for i in range(n):
        g1 = gates[i]
        if g1.name not in ("ccz", "ccx") or g1.cond is not None:
            continue

        # candidate ancilla: any qubit of g1 that is zero_init
        for a in g1.qubits:
            if a not in c.zero_init:
                continue
            if g1.name == "ccx" and a != g1.qubits[2]:
                continue  # ccx target must be the ancilla

            controls = tuple(q for q in g1.qubits if q != a)

            # find the next gate touching `a` after i
            j = None
            for k in range(i + 1, n):
                if a in gates[k].qubits:
                    j = k
                    break
            if j is None:
                continue

            g2 = gates[j]
            if g2.name != g1.name or g2.cond is not None:
                continue
            if g2.name == "ccx" and a != g2.qubits[2]:
                continue
            controls2 = tuple(q for q in g2.qubits if q != a)
            if frozenset(controls2) != frozenset(controls):
                continue
            # a must not appear again between i and j except exactly these two gates (guaranteed by construction)
            # also require g1 and g2 are genuinely identical pattern (same gate name, same control set)

            # Build the rewrite: keep everything up to and including i unchanged except we need
            # to only replace gate j (the second AND) with measurement-based erasure.
            new_gates = []
            fresh_cbit = c.nc

            for idx, g in enumerate(gates):
                if idx != j:
                    new_gates.append(g)
                    continue
                # Replace g2 (the AND on a) with H a; measure a; classically controlled correction; reset a
                new_gates.append(Gate("h", (a,)))
                new_gates.append(Gate("measure", (a,), cbit=fresh_cbit))
                if len(controls) == 2:
                    corr = Gate("cz", tuple(sorted(controls)), cond=fresh_cbit)
                elif len(controls) == 1:
                    corr = Gate("z", (controls[0],), cond=fresh_cbit)
                else:
                    continue
                new_gates.append(corr)
                new_gates.append(Gate("reset", (a,)))

            new_c = Circuit(c.n, new_gates, c.nc + 1, c.zero_init)
            return new_c, Req(eps=0.0, ancillas=0, measure=True)

    return c, Req()

"""
unmatched_tail_and_block_deferral_to_classical_fanout

For a trailing H-sandwiched CCZ(c1,c2,a) block, if `a` is provably |0> immediately before
the block (either declared in c.zero_init with no prior gate touching it, or produced by an
earlier, already-verified zero-setting sequence) AND the entire forward light-cone of `a`
after the block's closing H consists solely of diagonal gates (z/cz/ccz) using `a` only as
one of their qubits, then the block's only observable effect is a phase conditioned on
AND(c1,c2): measuring `a` right after the closing H and classically controlling the
downstream diagonal gates on that outcome reproduces the same phase pattern exactly,
since H;CCZ;H on a |0> ancilla deposits AND(c1,c2) into the Z-basis value of `a`. If `a`
is never touched again afterward, the (already phase-irrelevant) block can be deleted
outright. This circuit declares no clean ancillas (`c.zero_init` is empty and no qubit is
provably |0> from an empty prefix), so the precondition is never met here and the rule
must leave the circuit unchanged rather than assume zero-ness it cannot verify.
"""
from __future__ import annotations

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

_DIAG_USING_A = {"cz", "ccz", "z"}


def _find_block(gates, start):
    g0 = gates[start]
    if g0.name != "h":
        return None
    a = g0.qubits[0]
    if start + 2 >= len(gates):
        return None
    g1 = gates[start + 1]
    if g1.name != "ccz" or a not in g1.qubits:
        return None
    g2 = gates[start + 2]
    if g2.name != "h" or g2.qubits[0] != a:
        return None
    others = [q for q in g1.qubits if q != a]
    if len(others) != 2:
        return None
    c1, c2 = others
    return a, c1, c2, start, start + 2


def _is_zero_before(gates, upto_idx, qubit, zero_init):
    if qubit not in zero_init:
        return False
    for g in gates[:upto_idx]:
        if qubit in g.qubits:
            return False
    return True


def _classify_tail(gates, after_idx, a):
    touching = []
    for i in range(after_idx, len(gates)):
        g = gates[i]
        if a in g.qubits:
            touching.append(i)
    if not touching:
        return "dead", []
    for i in touching:
        g = gates[i]
        if g.name not in _DIAG_USING_A:
            return None
        if g.cond is not None:
            # Would require ANDing two classical conditions; our Gate only has one `cond`
            # field, so bail out to stay safe/exact.
            return None
    return "diag_only", touching


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)
    n = len(gates)
    zero_init = set(c.zero_init)

    found = None
    for start in range(n - 2):
        res = _find_block(gates, start)
        if res is None:
            continue
        a, c1, c2, blk_s, blk_e = res
        if not _is_zero_before(gates, blk_s, a, zero_init):
            continue
        cls = _classify_tail(gates, blk_e + 1, a)
        if cls is None:
            continue
        kind, touching = cls
        found = (a, c1, c2, blk_s, blk_e, kind, touching)
        break

    if found is None:
        # No qubit in this circuit is provably |0> before any candidate block (no declared
        # zero_init ancillas), so the precondition for the rewrite is never satisfied here.
        return c, Req()

    a, c1, c2, blk_s, blk_e, kind, touching = found

    if kind == "dead":
        new_gates = gates[:blk_s] + gates[blk_e + 1:]
        new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
        return new_c, Req(eps=0.0, ancillas=0, measure=False)

    new_cbit = c.nc
    new_gates = list(gates[:blk_s])
    new_gates.append(Gate("h", (a,)))
    new_gates.append(Gate("measure", (a,), cbit=new_cbit))
    new_gates.append(Gate("reset", (a,)))

    rest = gates[blk_e + 1:]
    touching_set = set(touching)
    offset = blk_e + 1
    for idx, g in enumerate(rest):
        true_idx = offset + idx
        if true_idx not in touching_set:
            new_gates.append(g)
            continue
        remaining_qubits = tuple(q for q in g.qubits if q != a)
        if g.cond is not None:
            return c, Req()
        if len(remaining_qubits) == 0:
            continue
        if g.name in ("z", "cz") and len(remaining_qubits) == 1:
            new_gates.append(Gate("z", remaining_qubits, cond=new_cbit))
        elif g.name == "ccz" and len(remaining_qubits) == 2:
            new_gates.append(Gate("cz", remaining_qubits, cond=new_cbit))
        elif g.name == "ccz" and len(remaining_qubits) == 1:
            new_gates.append(Gate("z", remaining_qubits, cond=new_cbit))
        else:
            return c, Req()

    new_c = Circuit(c.n, new_gates, c.nc + 1, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=True)

"""
Detects an X-basis accumulator qubit t set up by `x t; h t` and then only ever touched inside the
stretch by H-sandwiched CCZ(a,b,t) blocks (each H;CCZ;H == CCX(a,b->t) conjugated into the X basis)
and bare CX(j,t) gates between sandwiches. Each CCZ-sandwich XORs AND(a,b) into t's computational
value and each bare CX XORs its control into t, so the whole stretch realizes t ^= f(controls) for
a GF(2) polynomial f with quadratic part given by a symmetric adjacency matrix over the controls.
If that matrix has GF(2) rank 2, f's quadratic part factors as a product of two linear forms S,R;
we XOR S and R into two fresh ancillas (free Clifford CX), replace every Toffoli by a single
CCX(S,R->t), add the linear part back with CX, then uncompute the ancillas -- reproducing t's final
state exactly while collapsing however many quadratic terms there were into one Toffoli.
"""
import itertools
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _find_stretch(c: Circuit):
    gates = c.gates
    n = len(gates)
    for i, g in enumerate(gates):
        if g.name != "x":
            continue
        t = g.qubits[0]
        if i + 1 >= n or gates[i + 1].name != "h" or gates[i + 1].qubits[0] != t:
            continue
        start = i
        j = i + 2
        in_sandwich = False
        ccz_pairs = []
        cx_singles = []
        controls_used = set()
        ok = True
        end = j
        while j < n:
            gg = gates[j]
            if gg.name == "h" and gg.qubits[0] == t:
                in_sandwich = not in_sandwich
                j += 1
                end = j
                continue
            if gg.name == "ccz" and t in gg.qubits:
                if not in_sandwich:
                    ok = False
                    break
                others = tuple(q for q in gg.qubits if q != t)
                if len(others) != 2:
                    ok = False
                    break
                ccz_pairs.append(tuple(sorted(others)))
                controls_used.update(others)
                j += 1
                end = j
                continue
            if gg.name == "cx" and len(gg.qubits) == 2 and gg.qubits[1] == t:
                if in_sandwich:
                    ok = False
                    break
                cx_singles.append(gg.qubits[0])
                controls_used.add(gg.qubits[0])
                j += 1
                end = j
                continue
            if t in gg.qubits:
                # any other touch of t ends the stretch
                break
            if set(gg.qubits) & controls_used:
                # a gate touching a control we rely on, outside the recognized pattern: stop here
                break
            j += 1
            continue
        if in_sandwich:
            ok = False
        if not ok:
            continue
        if not ccz_pairs:
            continue
        if any(t in gg.qubits for gg in gates[:start]):
            continue
        if any(t in gg.qubits for gg in gates[end:]):
            continue
        yield dict(t=t, start=start, end=end, ccz_pairs=ccz_pairs, cx_singles=cx_singles,
                   controls=sorted(controls_used))


def _poly_truth_table(ctrls, ccz_pairs, cx_singles):
    """f(controls) as a dict: bitmask(over ctrls order) -> bit, for the XOR update t ^= f(...)."""
    m = len(ctrls)
    idx = {q: k for k, q in enumerate(ctrls)}
    tbl = {}
    for bits in range(1 << m):
        val = 0
        for (a, b) in ccz_pairs:
            ia, ib = idx[a], idx[b]
            if (bits >> ia) & 1 and (bits >> ib) & 1:
                val ^= 1
        for q in cx_singles:
            iq = idx[q]
            if (bits >> iq) & 1:
                val ^= 1
        tbl[bits] = val
    return tbl


def _gf2_rank2_factor(ctrls, ccz_pairs):
    """Symmetric zero-diagonal adjacency matrix A over ctrls from ccz_pairs; search for a partition
    S,R of ctrls (nonempty, disjoint, union = ctrls) with A[i][j] = 1 iff exactly one of i,j is in S
    and the other in R (bipartite complete-graph pattern == rank-2 factorization q_S * q_R)."""
    idx = {q: k for k, q in enumerate(ctrls)}
    m = len(ctrls)
    A = [[0] * m for _ in range(m)]
    for (a, b) in ccz_pairs:
        ia, ib = idx[a], idx[b]
        A[ia][ib] ^= 1
        A[ib][ia] ^= 1
    for bits in range(1, (1 << m) - 1):
        Rbits = ((1 << m) - 1) ^ bits
        ok = True
        for i in range(m):
            for j in range(i + 1, m):
                in_s_i = bool(bits & (1 << i))
                in_s_j = bool(bits & (1 << j))
                expected = 1 if (in_s_i != in_s_j) else 0
                if A[i][j] != expected:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            S = [ctrls[k] for k in range(m) if bits & (1 << k)]
            R = [ctrls[k] for k in range(m) if Rbits & (1 << k)]
            return S, R
    return None


def _verify_factorization(ctrls, ccz_pairs, cx_singles, S, R):
    """Brute-force check: t ^= f(ctrls) equals t ^= (AND(parity(S),parity(R))) XOR linear_part,
    where linear_part is whatever remains of cx_singles after accounting for the quadratic part
    (here we only use cx_singles as additional pure-linear XORs applied after the single CCX, so
    just check the full truth table matches: quad(bits) == parity(S,bits) & parity(R,bits))."""
    idx = {q: k for k, q in enumerate(ctrls)}
    m = len(ctrls)
    for bits in range(1 << m):
        quad = 0
        for (a, b) in ccz_pairs:
            ia, ib = idx[a], idx[b]
            if (bits >> ia) & 1 and (bits >> ib) & 1:
                quad ^= 1
        ps = 0
        for q in S:
            ps ^= (bits >> idx[q]) & 1
        pr = 0
        for q in R:
            pr ^= (bits >> idx[q]) & 1
        if quad != (ps & pr):
            return False
    return True


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    best = None
    for m in _find_stretch(c):
        if len(m["ccz_pairs"]) < 2:
            continue
        factored = _gf2_rank2_factor(m["controls"], m["ccz_pairs"])
        if factored is None:
            continue
        S, R = factored
        if not S or not R:
            continue
        if not _verify_factorization(m["controls"], m["ccz_pairs"], m["cx_singles"], S, R):
            continue
        best = (m, S, R)
        break
    if best is None:
        return c, Req()

    m, S, R = best
    t = m["t"]
    start, end = m["start"], m["end"]
    cx_singles = m["cx_singles"]

    s_anc = c.n
    r_anc = c.n + 1

    new_gates = list(c.gates[:start])

    new_gates.append(Gate("x", (t,)))
    new_gates.append(Gate("h", (t,)))

    for q in S:
        new_gates.append(Gate("cx", (q, s_anc)))
    for q in R:
        new_gates.append(Gate("cx", (q, r_anc)))

    new_gates.append(Gate("ccx", (s_anc, r_anc, t)))

    for q in reversed(R):
        new_gates.append(Gate("cx", (q, r_anc)))
    for q in reversed(S):
        new_gates.append(Gate("cx", (q, s_anc)))

    for q in cx_singles:
        new_gates.append(Gate("cx", (q, t)))

    new_gates.extend(c.gates[end:])

    new_c = Circuit(c.n + 2, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=2, measure=False)

"""mirrored_ccx_pair_to_single_ccz_on_spectator_ancilla

Finds ccx(a,b,t) ... S ... ccx(a,b,t) where t is a zero-initialized ancilla that is |0>
immediately before the first ccx (no earlier gate touches it), and S's only dependence on
t is via CX(t,x) gates (single fixed target x not in {a,b}), with a,b,x otherwise untouched
by S. Because t starts at 0: the first CCX sets t <- a&b; each CX(t,x) XORs (a&b) into x;
the second CCX (run on the still-untouched a,b) restores t to 0 exactly (since t already
equals a&b). So the whole sandwich is equivalent to applying CCX(a,b,x) once per CX(t,x)
occurrence (here exactly one), with t ending back at 0 -- eliminating one Toffoli. This is
an exact identity that depends on the ancilla's zero-init precondition, which pyzx/TKET
peephole optimizers do not exploit this way (they don't re-target a Toffoli's support).
"""
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _is_ccx_on(g: Gate, a, b, t):
    return g.name == "ccx" and set(g.qubits[:2]) == {a, b} and g.qubits[2] == t


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)
    n = len(gates)

    for i, g1 in enumerate(gates):
        if g1.name != "ccx":
            continue
        a, b, t = g1.qubits

        # t must be a zero-init ancilla and untouched before this gate.
        if t not in c.zero_init:
            continue
        touched_before = any(t in gates[k].qubits for k in range(i))
        if touched_before:
            continue

        # scan forward for the mirrored ccx(a,b,t)
        inner_idx = []
        x = None
        ok = True
        j = i + 1
        while j < n:
            g = gates[j]
            if _is_ccx_on(g, a, b, t):
                break
            if g.cond is not None:
                ok = False
                break
            if g.name == "cx" and g.qubits[0] == t and g.qubits[1] not in (a, b):
                cand_x = g.qubits[1]
                if x is None:
                    x = cand_x
                elif cand_x != x:
                    ok = False
                    break
                inner_idx.append(j)
            else:
                if a in g.qubits or b in g.qubits or t in g.qubits:
                    ok = False
                    break
                if x is not None and x in g.qubits:
                    ok = False
                    break
            j += 1
        else:
            ok = False

        if not ok or j >= n or x is None or not inner_idx:
            continue

        g2 = gates[j]
        if not _is_ccx_on(g2, a, b, t):
            continue
        # require exactly one CX(t,x) occurrence in between, so net effect of sandwich
        # on t is exactly: 0 -> a&b -> (unchanged by CX, since CX reads t not writes it) -> 0.
        if len(inner_idx) != 1:
            continue

        new_gates = []
        new_gates.extend(gates[:i])
        for k in range(i + 1, j):
            if k in inner_idx:
                new_gates.append(Gate("ccx", (a, b, x)))
            else:
                new_gates.append(gates[k])
        new_gates.extend(gates[j + 1:])

        new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
        return new_c, Req(eps=0.0, ancillas=0, measure=False)

    return c, Req()

"""
clifford_angle_snapping_of_near_dyadic_rz

Walks every rz gate, unifies angles that differ only by float noise, and
replaces any rz whose true angle is within numerical tolerance of a multiple
of pi/4 with the exact Clifford/T gate (s/sdg/z/t/tdg/identity) at zero cost.
Remaining rz's are snapped to the *nearest* multiple of pi/2 only when the
operator-norm cost sin(|delta|/2) of doing so fits inside a shared global
error budget (<=2.5e-4 total, spent greedily cheapest-first); angles whose
nearest-Clifford distance is large, or that would exceed the remaining
budget, are left as ordinary rz gates for gridsynth. Each replacement's
unitary is derived directly from rz's matrix definition
diag(e^{-i*theta/2}, e^{i*theta/2}) so the global phase/branch matches
exactly what the verifier's phase-invariant operator-norm check expects.
"""
from __future__ import annotations

import math

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

PI = math.pi
HALF_PI = PI / 2
EXACT_TOL = 1e-9          # treat as numerically identical (float noise)
DUP_TOL = 1e-6            # for unifying near-duplicate angles
MAX_BUDGET = 2.5e-4       # hard cap on total approximate error spent

# rz(theta) = diag(e^{-i theta/2}, e^{i theta/2}).
# For theta = k*(pi/4), k in 0..7 (mod 8), the exact (up to global phase) Clifford/T gate:
#   k=0: identity        k=1: t       k=2: s       k=3: ... (t*s, not single-gate) -> use s then t? no:
# diag(1, e^{i k pi/4}) * phase(-k pi/8) == rz(k*pi/4).
# Single native gates available: id, s(diag(1,i)), sdg(diag(1,-i)), z(diag(1,-1)), t(diag(1,e^{i pi/4})), tdg(diag(1,e^{-i pi/4})).
# These correspond to k (mod 8) of 0,2,6,4,1,7 respectively. k=3 and k=5 have no single native
# gate (t*s or t*z would be needed), so only snap those to a single gate when truly exact via k=3->no match: skip.
_K8_TO_GATE = {0: "id", 1: "t", 2: "s", 4: "z", 6: "sdg", 7: "tdg"}


def _nearest_k8(theta: float) -> tuple[int, float]:
    """Return (k mod 8, residual) with theta ~= k*(pi/4) + residual, residual in (-pi/8, pi/8]."""
    unit = PI / 4
    k = round(theta / unit)
    r = theta - k * unit
    return int(k) % 8, r


def _op_norm_err_for_angle_shift(delta: float) -> float:
    """Operator-norm distance between rz(theta) and rz(theta+delta) is sin(|delta|/2)."""
    return abs(math.sin(delta / 2.0))


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    rz_indices = [i for i, g in enumerate(c.gates) if g.name == "rz"]
    if not rz_indices:
        return c, Req()

    # Step 1: unify near-duplicate rz angles that differ only by float noise.
    canon_angles: list[float] = []
    for i in rz_indices:
        theta = c.gates[i].theta
        if not any(abs(theta - ca) < DUP_TOL for ca in canon_angles):
            canon_angles.append(theta)

    def canonicalize(theta: float) -> float:
        for ca in canon_angles:
            if abs(theta - ca) < DUP_TOL:
                return ca
        return theta

    exact_ops: dict[int, str] = {}
    approx_candidates: list[tuple[float, int, str]] = []

    for i in rz_indices:
        g = c.gates[i]
        theta = canonicalize(g.theta)
        k8, r = _nearest_k8(theta)

        if abs(r) < EXACT_TOL and k8 in _K8_TO_GATE:
            # Exact (within float precision) multiple of pi/4 that maps to a single native gate.
            exact_ops[i] = _K8_TO_GATE[k8]
            continue

        if k8 in _K8_TO_GATE:
            # Not exact, but close: candidate for budgeted approximate snap.
            cost = _op_norm_err_for_angle_shift(r)
            if cost > EXACT_TOL:
                approx_candidates.append((cost, i, _K8_TO_GATE[k8]))

    # Step 2: greedily spend budget on cheapest approximate snaps first.
    approx_candidates.sort(key=lambda x: x[0])
    spent = 0.0
    approx_ops: dict[int, str] = {}
    for cost, i, gate_name in approx_candidates:
        if spent + cost <= MAX_BUDGET:
            approx_ops[i] = gate_name
            spent += cost

    if not exact_ops and not approx_ops:
        return c, Req()

    def make_clifford_gate(name: str, qubit: int) -> list[Gate]:
        if name == "id":
            return []
        return [Gate(name, (qubit,))]

    new_gates = []
    for i, g in enumerate(c.gates):
        if i in exact_ops:
            new_gates.extend(make_clifford_gate(exact_ops[i], g.qubits[0]))
        elif i in approx_ops:
            new_gates.extend(make_clifford_gate(approx_ops[i], g.qubits[0]))
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)

    eps = min(spent, MAX_BUDGET) if approx_ops else 0.0
    return new_c, Req(eps=eps, ancillas=0, measure=False)

"""
cnot_conjugation_phase_gadget_merging

Slices the circuit at every H / measurement / non-rz-diagonal boundary. Within each
H-free slice, propagates the CNOT/CZ network forward as an F2 linear map on the wires,
so each rz(theta) on qubit q is tagged by the parity vector (subset of original slice
inputs) that algebraically sits on wire q at that point (CZ/CX update the map, CZ adds
no parity change itself). Two rz's in the same slice with identical parity vectors are
the *same* phase gadget exp(i*theta*Z_p/2): exact commutation of diagonal gadgets lets us
slide them together and fuse into rz(a+b), deleting one rotation and all its gates'
gridsynth T-cost. This is exact (no approximation), does not touch H/measurement
boundaries, and only fuses rotations that provably act as the same diagonal phase ---
a different mechanism from pyzx's graph-local gadget fusion, since it re-derives parity
through an already-resynthesized CNOT network.
"""
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _slices(c: Circuit):
    """Split gate indices into maximal runs that contain only cx/cz/rz (H-free, measurement-free)."""
    runs = []
    cur = []
    for i, g in enumerate(c.gates):
        if g.cond is not None:
            if cur:
                runs.append(cur)
                cur = []
            continue
        if g.name in ("cx", "cz", "rz"):
            cur.append(i)
        else:
            if cur:
                runs.append(cur)
                cur = []
    if cur:
        runs.append(cur)
    return runs


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = c.gates
    runs = _slices(c)

    # For each run, track per-qubit parity vector (as frozenset of basis-bit indices of the slice).
    # Basis bits = qubits touched within the run, each starts as its own singleton parity.
    to_delete = set()      # gate indices to remove (rz gates absorbed into another)
    theta_override = {}    # gate index -> new theta

    for run in runs:
        if len(run) < 2:
            continue
        qubits_in_run = sorted({q for i in run for q in gates[i].qubits})
        if not qubits_in_run:
            continue
        qidx = {q: k for k, q in enumerate(qubits_in_run)}
        # parity[q] = frozenset of basis-bit labels xored together currently on wire q
        parity = {q: frozenset([qidx[q]]) for q in qubits_in_run}

        # map: parity_frozenset -> list of rz gate indices (in order) with that parity, on any qubit
        seen = {}

        for i in run:
            g = gates[i]
            if g.name == "cx":
                ctrl, tgt = g.qubits
                parity[tgt] = parity[tgt] ^ parity[ctrl]
            elif g.name == "cz":
                pass  # CZ does not change the linear parity map (diagonal gate)
            elif g.name == "rz":
                (q,) = g.qubits
                p = parity[q]
                if p in seen:
                    first_idx = seen[p]
                    if first_idx not in to_delete:
                        base_theta = theta_override.get(first_idx, gates[first_idx].theta)
                        new_theta = base_theta + g.theta
                        theta_override[first_idx] = new_theta
                        to_delete.add(i)
                        # keep "seen[p]" pointing at the surviving (fused) gate
                else:
                    seen[p] = i

    if not to_delete:
        return c, Req()

    new_gates = []
    for i, g in enumerate(gates):
        if i in to_delete:
            continue
        if i in theta_override:
            new_gates.append(Gate("rz", g.qubits, theta=theta_override[i]))
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
cnot_conjugation_phase_gadget_merging

Slices the circuit at every non-diagonal gate (h, sx, sxdg, x, y, swap, ccx, ccz, cond,
measure/reset). Within each such slice, propagates the CNOT network forward as an F2
linear map on the wires: each wire carries a parity vector (XOR-subset of the slice's
initial wire values). cz/t/tdg/s/sdg/rz are all diagonal and do not change this map, only
cx does. Two rz's in the same slice with identical parity vectors are literally the same
phase gadget exp(i*theta*Z_p/2) (same p), so they commute past everything diagonal and past
the cx's that preserve the map, and fuse exactly into rz(a+b) at one of their positions,
deleting the other. This is exact (zero error), never touches H/measurement boundaries,
and fuses gadgets that are only equal once CNOT-propagated -- not local ZX-graph neighbors,
so it is a different mechanism than pyzx's gadget fusion / TKET peephole phase folding.
"""
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

_DIAGONAL = {"cz", "rz", "t", "tdg", "s", "sdg", "z"}
_LINEAR_UPDATE = {"cx"}  # gates that update the F2 parity map
_PASSTHROUGH = _DIAGONAL | _LINEAR_UPDATE


def _slices(c: Circuit):
    """Split gate indices into maximal runs containing only diagonal 1q/2q gates and cx
    (no H/SWAP/Toffoli/measure/cond), i.e. runs where an F2 linear parity map is well defined."""
    runs = []
    cur = []
    for i, g in enumerate(c.gates):
        if g.cond is not None:
            if cur:
                runs.append(cur)
                cur = []
            continue
        if g.name in _PASSTHROUGH:
            cur.append(i)
        else:
            if cur:
                runs.append(cur)
                cur = []
    if cur:
        runs.append(cur)
    return runs


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = c.gates
    runs = _slices(c)

    to_delete = set()      # gate indices to remove (rz gates absorbed into another)
    theta_override = {}    # gate index -> new theta

    for run in runs:
        if len(run) < 2:
            continue
        qubits_in_run = sorted({q for i in run for q in gates[i].qubits})
        if not qubits_in_run:
            continue
        qidx = {q: k for k, q in enumerate(qubits_in_run)}
        # parity[q] = frozenset of basis-bit labels (ints) xored together currently on wire q
        parity = {q: frozenset([qidx[q]]) for q in qubits_in_run}

        # map: parity_frozenset -> gate index of the surviving rz with that parity
        seen = {}

        for i in run:
            g = gates[i]
            if g.name == "cx":
                ctrl, tgt = g.qubits
                parity[tgt] = parity[tgt] ^ parity[ctrl]
            elif g.name == "rz":
                (q,) = g.qubits
                p = parity[q]
                if p in seen:
                    first_idx = seen[p]
                    if first_idx not in to_delete:
                        base_theta = theta_override.get(first_idx, gates[first_idx].theta)
                        new_theta = base_theta + g.theta
                        theta_override[first_idx] = new_theta
                        to_delete.add(i)
                        # seen[p] continues to point at the surviving (fused) gate
                else:
                    seen[p] = i
            # cz, t, tdg, s, sdg, z: diagonal, do not change parity map and are left in place

    if not to_delete:
        return c, Req()

    new_gates = []
    for i, g in enumerate(gates):
        if i in to_delete:
            continue
        if i in theta_override:
            new_gates.append(Gate("rz", g.qubits, theta=theta_override[i]))
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
cnot_conjugation_phase_gadget_merging

Extends the H-free "slice" over which an F2 parity map is tracked: diagonal gates (rz, t,
tdg, s, sdg, z, cz) never change the map; cx updates target-parity by XOR of control-parity;
swap just permutes which wire holds which parity vector (it does not require ending the
slice); x on a wire flips that wire's *constant* offset but not its linear part, so it is
also passed through by tracking an affine (linear part, constant bit) pair instead of pure
linear. Two rz's in the same slice whose (linear, constant) parity data match represent the
same phase gadget exp(i*theta*Z_p/2) (up to a global sign from the constant bit, folded into
the angle), so they commute together and fuse exactly into one rz(a+b), deleting the other.
Only h/sx/sxdg/ccx/ccz/measure/reset/cond close a slice (those break the affine-linear
tracking). This is exact (zero error) and targets gadgets that are only equal once CNOT/SWAP/X
propagated through -- not local ZX-graph neighbors -- so it is complementary to pyzx gadget
fusion and TKET peephole phase folding.
"""
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

_DIAGONAL = {"cz", "rz", "t", "tdg", "s", "sdg", "z"}
_BOUNDARY = {"h", "sx", "sxdg", "ccx", "ccz", "measure", "reset", "y"}


def _slices(c: Circuit):
    """Split gate indices into maximal runs of gates that keep an affine-F2 parity map
    well defined on every wire: rz/t/tdg/s/sdg/z/cz (diagonal, pass through unchanged),
    cx (updates target parity += control parity), x (flips constant offset of its wire),
    swap (permutes wire->parity assignment). Anything else (h, sx, toffoli, measure,
    cond, y) ends the current run."""
    runs = []
    cur = []
    for i, g in enumerate(c.gates):
        if g.cond is not None:
            if cur:
                runs.append(cur)
                cur = []
            continue
        if g.name in _DIAGONAL or g.name in ("cx", "x", "swap"):
            cur.append(i)
        else:
            if cur:
                runs.append(cur)
                cur = []
    if cur:
        runs.append(cur)
    return runs


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = c.gates
    runs = _slices(c)

    to_delete = set()      # gate indices to remove (rz gates absorbed into another)
    theta_override = {}    # gate index -> new theta

    for run in runs:
        if len(run) < 2:
            continue
        qubits_in_run = sorted({q for i in run for q in gates[i].qubits})
        if not qubits_in_run:
            continue
        qidx = {q: k for k, q in enumerate(qubits_in_run)}
        # affine parity per wire: (linear frozenset of basis-bit labels, constant bit 0/1)
        linear = {q: frozenset([qidx[q]]) for q in qubits_in_run}
        const = {q: 0 for q in qubits_in_run}

        # map: (linear, const) -> gate index of the surviving rz with that parity
        seen = {}

        for i in run:
            g = gates[i]
            if g.name == "cx":
                ctrl, tgt = g.qubits
                linear[tgt] = linear[tgt] ^ linear[ctrl]
                const[tgt] = const[tgt] ^ const[ctrl]
            elif g.name == "x":
                (q,) = g.qubits
                const[q] = const[q] ^ 1
            elif g.name == "swap":
                a, b = g.qubits
                linear[a], linear[b] = linear[b], linear[a]
                const[a], const[b] = const[b], const[a]
            elif g.name == "rz":
                (q,) = g.qubits
                key = (linear[q], const[q])
                # a flipped constant bit means exp(i*theta*Z_p/2) acts on the complemented
                # basis function, which is the same operator up to swapping +theta/2 <-> -theta/2
                # on that branch; to stay exact we only fuse when const matches exactly.
                if key in seen:
                    first_idx = seen[key]
                    if first_idx not in to_delete:
                        base_theta = theta_override.get(first_idx, gates[first_idx].theta)
                        new_theta = base_theta + g.theta
                        theta_override[first_idx] = new_theta
                        to_delete.add(i)
                else:
                    seen[key] = i
            # cz, t, tdg, s, sdg, z: diagonal, do not change parity map and are left in place

    if not to_delete:
        return c, Req()

    new_gates = []
    for i, g in enumerate(gates):
        if i in to_delete:
            continue
        if i in theta_override:
            new_gates.append(Gate("rz", g.qubits, theta=theta_override[i]))
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
Fuses maximal single-qubit runs of {rz, h, s, sdg, t, tdg, x, y, z} (no intervening
2q/3q gate on that qubit) into one 2x2 unitary U, then re-synthesizes U minimally:

  - if U is Clifford (within tolerance), replace with the exact Clifford gate(s) -> 0 T.
  - if U is a Z-axis rotation up to Cliffords (i.e. the ZXZ decomposition has the middle
    "X" angle a multiple of pi, so H Rz(beta) H collapses to a Clifford), collapse the whole
    run to a single rz (plus Cliffords) -> only 1 non-Clifford angle instead of up to 3.
  - otherwise emit the canonical ZXZ form rz(gamma); h; rz(beta); h; rz(alpha), the minimal
    universal decomposition. Because pyzx/TKET never fuse rotations separated by a Hadamard
    (that's diagonal-only resp. 2-qubit-block-local), a run such as rz(a) h rz(b) h rz(c) is
    otherwise synthesized as 3 independent arbitrary rz's by gridsynth; collapsing it to a run
    with fewer (or snapped-to-Clifford) arbitrary angles directly reduces T-count.

Correctness: each run is re-expressed as the exact same 2x2 unitary matrix (verified here by
explicit multiplication/decomposition and reconstruction check, up to global phase, which gates
always ignore). We only ever substitute an *equal* unitary (eps=0) or, when a middle angle is
within the small allowed budget of a Clifford multiple of pi/2, we snap it there and account for
that approximation explicitly in Req(eps=...).
"""
from __future__ import annotations

import math
from itertools import product

import numpy as np

from circuitevolve.circuit import Circuit, Gate, matrix
from circuitevolve.verifier import Req

_RUN_GATES = {"rz", "h", "s", "sdg", "t", "tdg", "x", "y", "z"}
TOL = 1e-9
MAX_EPS = 2.5e-4
# per-run approx budget: keep it small and divide fairly; we rarely need it since snapping is
# only attempted when the angle is already extremely close to a Clifford multiple.
SNAP_TOL = 1e-4  # radians-ish; if within this of a Clifford angle, treat distance as ~ (tol^2)/2


def _op_dist(A: np.ndarray, B: np.ndarray) -> float:
    """Phase-invariant operator-norm distance between two 2x2 unitaries."""
    idx = np.unravel_index(np.argmax(np.abs(B)), B.shape)
    if abs(B[idx]) < 1e-14:
        return float(np.linalg.norm(A - B, ord=2))
    ph = A[idx] / B[idx] if abs(A[idx]) > 1e-14 else 1.0
    if abs(ph) > 1e-14:
        ph = ph / abs(ph)
    return float(np.linalg.norm(A - ph * B, ord=2))


def _build_clifford_table():
    gens = {
        "h": np.array([[1, 1], [1, -1]], dtype=complex) / math.sqrt(2),
        "x": np.array([[0, 1], [1, 0]], dtype=complex),
        "y": np.array([[0, -1j], [1j, 0]], dtype=complex),
        "z": np.diag([1, -1]).astype(complex),
        "s": np.diag([1, 1j]).astype(complex),
        "sdg": np.diag([1, -1j]).astype(complex),
    }
    names = list(gens.keys())
    seqs = [()]
    for L in (1, 2, 3):
        for combo in product(names, repeat=L):
            seqs.append(combo)

    table = []
    for seq in seqs:
        M = np.eye(2, dtype=complex)
        for nm in seq:
            M = gens[nm] @ M
        table.append((seq, M))
    return table


_CLIFFORD_TABLE = _build_clifford_table()


def _is_clifford_u(U: np.ndarray, tol=1e-6):
    best_seq, best_d = None, 1e9
    for seq, M in _CLIFFORD_TABLE:
        d = _op_dist(U, M)
        if d < best_d:
            best_d, best_seq = d, seq
    if best_d < tol:
        return [nm for nm in best_seq]
    return None


def _zxz_decompose(U: np.ndarray):
    """Decompose U (2x2 unitary, up to global phase) into Rz(alpha) H Rz(beta) H Rz(gamma)
    (matrix-product order; circuit order is gamma, h, beta, h, alpha)."""
    H = np.array([[1, 1], [1, -1]], dtype=complex) / math.sqrt(2)

    def Rz(t):
        return np.diag([np.exp(-0.5j * t), np.exp(0.5j * t)])

    detU = np.linalg.det(U)
    phase = detU ** -0.5
    Un = U * phase

    a11, a21 = Un[0, 0], Un[1, 0]
    a22 = Un[1, 1]

    cos_b2 = float(np.clip(abs(a11), 0.0, 1.0))
    b = 2 * math.acos(cos_b2)

    if abs(math.sin(b / 2)) < 1e-9:
        apc = -2 * np.angle(a11) if abs(a11) > 1e-12 else 0.0
        a, cc = apc, 0.0
    elif abs(cos_b2) < 1e-9:
        amc = -2 * np.angle(a21) if abs(a21) > 1e-12 else 0.0
        a, cc = amc, 0.0
    else:
        apc = -2 * np.angle(a22)
        amc = -2 * np.angle(a21)
        a = (apc + amc) / 2
        cc = (apc - amc) / 2

    alpha = a - math.pi / 2
    gamma = cc + math.pi / 2
    beta = b

    Rec = Rz(alpha) @ H @ Rz(beta) @ H @ Rz(gamma)
    return alpha, beta, gamma, Rec


def _wrap(x):
    return ((x + math.pi) % (2 * math.pi)) - math.pi


def _nearest_clifford_quarter(theta):
    """Return (snapped_theta, dist_in_radians) where snapped_theta is the nearest multiple of pi/2
    (Clifford Z-rotation up to global phase: I, S, Z, Sdg pattern -> multiples of pi/2)."""
    k = round(theta / (math.pi / 2))
    snapped = k * math.pi / 2
    return snapped, abs(_wrap(theta - snapped))


def _collect_runs(c: Circuit):
    n = c.n
    runs = []
    cur_run = {q: [] for q in range(n)}
    for i, g in enumerate(c.gates):
        touched = set(g.qubits)
        is_simple_1q = (len(g.qubits) == 1 and g.name in _RUN_GATES and g.cond is None)
        for q in range(n):
            if q in touched:
                if is_simple_1q:
                    cur_run[q].append(i)
                else:
                    if len(cur_run[q]) >= 2:
                        runs.append((q, list(cur_run[q])))
                    cur_run[q] = []
    for q in range(n):
        if len(cur_run[q]) >= 2:
            runs.append((q, list(cur_run[q])))
    return runs


def _count_arb_rz(gates):
    from circuitevolve.circuit import is_arbitrary_rz
    return sum(1 for g in gates if is_arbitrary_rz(g))


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    from circuitevolve.circuit import is_arbitrary_rz

    runs = _collect_runs(c)
    if not runs:
        return c, Req()

    replacement = {}
    any_change = False
    total_eps_spent = 0.0
    used_measure = False

    for q, idxs in runs:
        orig_gates = [c.gates[i] for i in idxs]
        orig_arb = _count_arb_rz(orig_gates)
        if orig_arb < 1:
            continue  # nothing non-Clifford to save; skip (avoid churn / risk)

        U = np.eye(2, dtype=complex)
        for g in orig_gates:
            U = matrix(g) @ U

        new_gates = None
        eps_here = 0.0

        cliff = _is_clifford_u(U, tol=1e-6)
        if cliff is not None:
            new_gates = [Gate(nm, (q,)) for nm in cliff]
        else:
            alpha, beta, gamma, Rec = _zxz_decompose(U)
            d_exact = _op_dist(U, Rec)
            if d_exact > 1e-6:
                continue  # decomposition failed numerically; skip this run to be safe

            # Try snapping beta to nearest Clifford multiple of pi/2 (collapses H Rz(beta) H
            # to a Clifford, leaving only the single Rz(alpha+/-gamma)-style combination).
            beta_snap, beta_d = _nearest_clifford_quarter(beta)
            snapped_as_z = False
            if beta_d < SNAP_TOL:
                # candidate: replace beta with beta_snap exactly, reconstruct, measure true distance
                H = np.array([[1, 1], [1, -1]], dtype=complex) / math.sqrt(2)

                def Rz(t):
                    return np.diag([np.exp(-0.5j * t), np.exp(0.5j * t)])

                Rec_snap = Rz(alpha) @ H @ Rz(beta_snap) @ H @ Rz(gamma)
                d_snap = _op_dist(U, Rec_snap)
                if d_snap <= MAX_EPS:
                    k = int(round(beta_snap / (math.pi / 2))) % 4
                    # H Rz(k*pi/2) H as explicit Clifford/rz-free or single-rz combos:
                    # k=0: H*I*H = I
                    # k=2: H*Z*H = X
                    # k=1: H*S*H -> not a pure Z rotation combined with others in general;
                    #      but Rz(alpha) H Rz(pi/2) H Rz(gamma) = Rz(alpha) * Rx(pi/2) * Rz(gamma),
                    #      which is still a single non-Clifford-free decomposition unless we also
                    #      fold Rx(pi/2) as Clifford (it's SX up to phase, which IS Clifford).
                    if k == 0:
                        mid = []
                    elif k == 2:
                        mid = [Gate("x", (q,))]
                    elif k == 1:
                        mid = [Gate("sx", (q,))]
                    else:  # k == 3
                        mid = [Gate("sxdg", (q,))]
                    cand = [Gate("rz", (q,), theta=_wrap(gamma)), *mid, Gate("rz", (q,), theta=_wrap(alpha))]
                    # verify candidate reconstructs U within MAX_EPS via direct matrix product
                    Mc = np.eye(2, dtype=complex)
                    for gg in cand:
                        Mc = matrix(gg) @ Mc
                    d_cand = _op_dist(U, Mc)
                    if d_cand <= MAX_EPS and _count_arb_rz(cand) < orig_arb:
                        new_gates = cand
                        eps_here = d_cand
                        snapped_as_z = True

            if not snapped_as_z:
                new_gates = [
                    Gate("rz", (q,), theta=_wrap(gamma)),
                    Gate("h", (q,)),
                    Gate("rz", (q,), theta=_wrap(beta)),
                    Gate("h", (q,)),
                    Gate("rz", (q,), theta=_wrap(alpha)),
                ]
                eps_here = d_exact  # essentially 0

        new_arb = _count_arb_rz(new_gates)
        if new_arb >= orig_arb:
            continue  # no win on arbitrary-rz count for this run; skip

        if total_eps_spent + eps_here > MAX_EPS:
            continue  # would exceed global approx budget; skip this run

        replacement[idxs[0]] = new_gates
        for i in idxs[1:]:
            replacement[i] = []
        total_eps_spent += eps_here
        any_change = True

    if not any_change:
        return c, Req()

    new_gate_list = []
    for i, g in enumerate(c.gates):
        if i in replacement:
            new_gate_list.extend(replacement[i])
        else:
            new_gate_list.append(g)

    new_c = Circuit(c.n, new_gate_list, c.nc, c.zero_init)
    return new_c, Req(eps=total_eps_spent, ancillas=0, measure=used_measure)

"""
Finds maximal runs of single-qubit Clifford+rz gates (h, s, sdg, t, tdg, x, y, z, rz) acting on one
qubit with no intervening multi-qubit gate on that qubit, multiplies them into one 2x2 unitary U,
and re-emits U with the fewest non-Clifford rz angles possible: Clifford-only (0 T) if U is Clifford
within tolerance; a single rz (plus Cliffords) if U's canonical ZXZ decomposition has a middle "X"
angle that is itself (near) Clifford, collapsing H Rz(beta) H to a Clifford conjugation; otherwise the
minimal 3-angle ZXZ form rz-h-rz-h-rz. Because pyzx/TKET never fuse rotations separated by a Hadamard,
such runs would otherwise reach gridsynth as 2-3 independent arbitrary rz's; collapsing the run can only
reduce (never increase) the arbitrary-rz count, and the run is only replaced when it strictly does so.
Each candidate replacement is checked by explicit matrix reconstruction (phase-invariant distance)
before being accepted, so every substitution is either exact (eps=0) or within the declared budget.
"""
from __future__ import annotations

import math
from itertools import product

import numpy as np

from circuitevolve.circuit import Circuit, Gate, matrix, is_arbitrary_rz
from circuitevolve.verifier import Req

_RUN_GATES = {"rz", "h", "s", "sdg", "t", "tdg", "x", "y", "z"}
MAX_EPS = 2.5e-4
SNAP_TOL = 3e-3  # radians: try snapping the ZXZ middle angle to a Clifford quarter-turn if this close


def _op_dist(A: np.ndarray, B: np.ndarray) -> float:
    """Phase-invariant operator-norm distance between two 2x2 unitaries."""
    idx = np.unravel_index(np.argmax(np.abs(B)), B.shape)
    if abs(B[idx]) < 1e-14:
        return float(np.linalg.norm(A - B, ord=2))
    ph = A[idx] / B[idx] if abs(A[idx]) > 1e-14 else 1.0
    if abs(ph) > 1e-14:
        ph = ph / abs(ph)
    return float(np.linalg.norm(A - ph * B, ord=2))


def _apply_seq(gates, q=0):
    """Matrix of a list of 1-qubit Gates applied in circuit order (first gate acts first)."""
    U = np.eye(2, dtype=complex)
    for g in gates:
        U = matrix(g) @ U
    return U


def _build_clifford_table():
    gens = {
        "h": np.array([[1, 1], [1, -1]], dtype=complex) / math.sqrt(2),
        "x": np.array([[0, 1], [1, 0]], dtype=complex),
        "y": np.array([[0, -1j], [1j, 0]], dtype=complex),
        "z": np.diag([1, -1]).astype(complex),
        "s": np.diag([1, 1j]).astype(complex),
        "sdg": np.diag([1, -1j]).astype(complex),
    }
    names = list(gens.keys())
    seqs = [()]
    for L in (1, 2, 3):
        for combo in product(names, repeat=L):
            seqs.append(combo)
    table = []
    for seq in seqs:
        M = np.eye(2, dtype=complex)
        for nm in seq:
            M = gens[nm] @ M
        table.append((seq, M))
    return table


_CLIFFORD_TABLE = _build_clifford_table()


def _is_clifford_u(U: np.ndarray, tol=1e-6):
    best_seq, best_d = None, 1e9
    for seq, M in _CLIFFORD_TABLE:
        d = _op_dist(U, M)
        if d < best_d:
            best_d, best_seq = d, seq
    if best_d < tol:
        return list(best_seq)
    return None


def _wrap(x):
    return ((x + math.pi) % (2 * math.pi)) - math.pi


def _Rz(t):
    return np.diag([np.exp(-0.5j * t), np.exp(0.5j * t)])


_H = np.array([[1, 1], [1, -1]], dtype=complex) / math.sqrt(2)


def _zxz_decompose(U: np.ndarray):
    """Decompose U (2x2 unitary, up to global phase) so that, in circuit-application order
    (first gate acts first on the state), U == Rz(alpha) @ H @ Rz(beta) @ H @ Rz(gamma)
    i.e. circuit order is: rz(gamma); h; rz(beta); h; rz(alpha)."""
    detU = np.linalg.det(U)
    phase = detU ** -0.5
    Un = U * phase
    # Un = H Rz(alpha) H Rz(beta) H Rz(gamma) H  up-to-global phase representation trick:
    # easier: directly solve for ZYZ-like via standard formula on Un (SU(2)).
    a11, a21 = Un[0, 0], Un[1, 0]
    a22 = Un[1, 1]

    cos_b2 = float(np.clip(abs(a11), 0.0, 1.0))
    b = 2 * math.acos(cos_b2)

    if abs(math.sin(b / 2)) < 1e-9:
        apc = -2 * np.angle(a11) if abs(a11) > 1e-12 else 0.0
        a, cc = apc, 0.0
    elif abs(cos_b2) < 1e-9:
        amc = -2 * np.angle(a21) if abs(a21) > 1e-12 else 0.0
        a, cc = amc, 0.0
    else:
        apc = -2 * np.angle(a22)
        amc = -2 * np.angle(a21)
        a = (apc + amc) / 2
        cc = (apc - amc) / 2

    alpha = a - math.pi / 2
    gamma = cc + math.pi / 2
    beta = b

    Rec = _Rz(alpha) @ _H @ _Rz(beta) @ _H @ _Rz(gamma)
    return alpha, beta, gamma, Rec


def _nearest_quarter(theta):
    k = round(theta / (math.pi / 2))
    snapped = k * math.pi / 2
    return snapped, abs(_wrap(theta - snapped))


def _count_arb_rz(gates):
    return sum(1 for g in gates if is_arbitrary_rz(g))


def _collect_runs(c: Circuit):
    """Maximal runs (consecutive gate indices) of single-qubit gates in _RUN_GATES, cond=None,
    all on the same qubit, with no other gate touching that qubit in between."""
    n = c.n
    runs = []
    cur = {q: [] for q in range(n)}
    for i, g in enumerate(c.gates):
        is_simple = (len(g.qubits) == 1 and g.name in _RUN_GATES and g.cond is None)
        if is_simple:
            q = g.qubits[0]
            cur[q].append(i)
        else:
            for q in g.qubits:
                if len(cur[q]) >= 2:
                    runs.append((q, list(cur[q])))
                cur[q] = []
    for q in range(n):
        if len(cur[q]) >= 2:
            runs.append((q, list(cur[q])))
    return runs


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    runs = _collect_runs(c)
    if not runs:
        return c, Req()

    replacement = {}
    total_eps_spent = 0.0
    any_change = False

    for q, idxs in runs:
        orig_gates = [c.gates[i] for i in idxs]
        orig_arb = _count_arb_rz(orig_gates)
        if orig_arb < 2:
            continue  # need at least 2 arbitrary rz's split by Cliffords to have a win

        U = _apply_seq(orig_gates)

        new_gates = None
        eps_here = 0.0

        cliff = _is_clifford_u(U, tol=1e-6)
        if cliff is not None:
            new_gates = [Gate(nm, (q,)) for nm in cliff]
            eps_here = 0.0
        else:
            try:
                alpha, beta, gamma, Rec = _zxz_decompose(U)
            except Exception:
                continue
            d_exact = _op_dist(U, Rec)
            if d_exact > 1e-6:
                continue

            best = None  # (new_gates, eps_here, arb_count)

            # candidate A: snap beta to nearest Clifford quarter turn (collapses middle rotation)
            beta_snap, beta_d = _nearest_quarter(beta)
            if beta_d < SNAP_TOL:
                Rec_snap = _Rz(alpha) @ _H @ _Rz(beta_snap) @ _H @ _Rz(gamma)
                d_snap = _op_dist(U, Rec_snap)
                if d_snap <= MAX_EPS:
                    k = int(round(beta_snap / (math.pi / 2))) % 4
                    if k == 0:
                        mid = []
                    elif k == 2:
                        mid = [Gate("x", (q,))]
                    elif k == 1:
                        mid = [Gate("sx", (q,))]
                    else:
                        mid = [Gate("sxdg", (q,))]
                    cand = [Gate("rz", (q,), theta=_wrap(gamma)), *mid, Gate("rz", (q,), theta=_wrap(alpha))]
                    Mc = _apply_seq(cand)
                    d_cand = _op_dist(U, Mc)
                    if d_cand <= MAX_EPS:
                        cand_arb = _count_arb_rz(cand)
                        if cand_arb < orig_arb:
                            cand_merged = _merge_adjacent_rz(cand)
                            best = (cand_merged, d_cand, _count_arb_rz(cand_merged))

            # candidate B: exact minimal ZXZ (3 angles, but fused from possibly more originally)
            cand_zxz = [
                Gate("rz", (q,), theta=_wrap(gamma)),
                Gate("h", (q,)),
                Gate("rz", (q,), theta=_wrap(beta)),
                Gate("h", (q,)),
                Gate("rz", (q,), theta=_wrap(alpha)),
            ]
            cand_zxz_merged = _merge_adjacent_rz(cand_zxz)
            zxz_arb = _count_arb_rz(cand_zxz_merged)
            if zxz_arb < orig_arb:
                cand_eps = d_exact
                if best is None or zxz_arb < best[2]:
                    best = (cand_zxz_merged, cand_eps, zxz_arb)

            if best is None:
                continue
            new_gates, eps_here, _ = best

        new_arb = _count_arb_rz(new_gates)
        if new_arb >= orig_arb:
            continue

        if total_eps_spent + eps_here > MAX_EPS:
            continue

        replacement[idxs[0]] = new_gates
        for i in idxs[1:]:
            replacement[i] = []
        total_eps_spent += eps_here
        any_change = True

    if not any_change:
        return c, Req()

    new_gate_list = []
    for i, g in enumerate(c.gates):
        if i in replacement:
            new_gate_list.extend(replacement[i])
        else:
            new_gate_list.append(g)

    new_c = Circuit(c.n, new_gate_list, c.nc, c.zero_init)
    return new_c, Req(eps=total_eps_spent, ancillas=0, measure=False)


def _merge_adjacent_rz(gates):
    """Merge consecutive rz gates on the same (sole) qubit into one; drop zero-angle rz's."""
    out = []
    for g in gates:
        if g.name == "rz" and out and out[-1].name == "rz":
            theta = _wrap(out[-1].theta + g.theta)
            out[-1] = Gate("rz", g.qubits, theta=theta)
        else:
            out.append(g)
    cleaned = []
    for g in out:
        if g.name == "rz" and abs(_wrap(g.theta)) < 1e-9:
            continue
        cleaned.append(g)
    return cleaned

"""
Repeat-until-success (RUS)-style exact reduction for near-Clifford rz rotations.

For each rz(theta) whose angle, after peeling the nearest Clifford multiple of pi/2,
leaves a residual that is (numerically, within float tolerance) an exact multiple of
pi/4 -- i.e. the gate is secretly Clifford+T but gridsynth/pyzx did not snap it because
of a tiny numeric offset below their snapping tolerance -- we replace it by the exact
Clifford+T decomposition (S/Z/Sdg times T/Tdg) with zero error cost. This is correct
because rz(k*pi/2 + m*pi/4) = Clifford(k) * (T or Tdg)^m exactly, up to global phase,
which the verifier ignores; no approximation or ancilla is used, so eps=0 and the
rewrite is exact. We do NOT invent a non-literature RUS ancilla gadget (an earlier
attempt at a made-up ancilla-coin-flip circuit failed verification because it did not
implement any true small-angle rotation identity); instead this rule only fires when
exactness can be guaranteed, so it can never fail the equivalence check, and it still
removes T-count-expensive arbitrary-rz instances whenever this numeric coincidence
occurs anywhere in the circuit.
"""
from __future__ import annotations

import math

from circuitevolve.circuit import Circuit, Gate, _quarter_turns
from circuitevolve.verifier import Req

PI = math.pi
_TOL = 1e-7


def _clifford_for_k(k: int, qubit: int) -> list:
    k = k % 4
    if k == 0:
        return []
    if k == 1:
        return [Gate("s", (qubit,))]
    if k == 2:
        return [Gate("z", (qubit,))]
    return [Gate("sdg", (qubit,))]


def _exact_decomposition(theta: float, qubit: int):
    """If theta is, within _TOL, an exact multiple of pi/4, return the exact Clifford+T
    gate list implementing rz(theta) on `qubit` (up to global phase). Else return None."""
    k8 = theta / (PI / 4)
    k8r = round(k8)
    if abs(k8 - k8r) > _TOL:
        return None
    k8r = int(k8r) % 8
    k_quarter, odd = divmod(k8r, 2)   # k8r = 2*k_quarter + odd, odd in {0,1}
    gates = _clifford_for_k(k_quarter, qubit)
    if odd:
        gates = gates + [Gate("t", (qubit,))]
    return gates


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    targets = {}
    for idx, g in enumerate(c.gates):
        if g.name != "rz":
            continue
        if _quarter_turns(g.theta) is not None:
            continue  # already recognized as Clifford/T-like by counts()
        dec = _exact_decomposition(g.theta, g.qubits[0])
        if dec is not None:
            targets[idx] = dec

    if not targets:
        return c, Req()

    new_gates = []
    for idx, g in enumerate(c.gates):
        if idx in targets:
            new_gates.extend(targets[idx])
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
Approximate-Clifford snap for near-Clifford rz rotations, within the allowed error budget.

Several rz(theta) angles in this circuit are a small residual away from an exact multiple
of pi/4 (e.g. 0.5 away from 0, or 0.015 away from a Clifford point), after peeling off the
Clifford part gridsynth/pyzx already handle exactly. Replacing such an rz by the nearest
exact Clifford rotation (I/S/Z/Sdg/T/Tdg, up to global phase) incurs a bounded operator-norm
error of sin(|delta|/2) <= |delta|/2, where delta is the angular residual. We only perform
the swap when the resulting total spent error (summed over all rewritten gates) stays within
the allowed approx budget (<= 2.5e-4), spending the smallest-delta instances first so we get
the most T-count removed per unit of error. This is exact in its mechanism (no ancilla, no
measurement) and the verifier directly checks the achieved operator-norm distance, so the
rewrite is correct by construction: we only emit a swap when the true computed distance is
<= the remaining budget.
"""
from __future__ import annotations

import math

from circuitevolve.circuit import Circuit, Gate, _quarter_turns
from circuitevolve.verifier import Req

PI = math.pi
_BUDGET = 2.50e-4


def _clifford_gates_for_k(k_mod8: int, qubit: int) -> list:
    """Exact Clifford+T gate(s) implementing rz(k_mod8 * pi/4) up to global phase."""
    k_mod8 %= 8
    k_quarter, odd = divmod(k_mod8, 2)
    k_quarter %= 4
    gates = []
    if k_quarter == 1:
        gates.append(Gate("s", (qubit,)))
    elif k_quarter == 2:
        gates.append(Gate("z", (qubit,)))
    elif k_quarter == 3:
        gates.append(Gate("sdg", (qubit,)))
    if odd:
        gates.append(Gate("t", (qubit,)))
    return gates


def _nearest_octant_residual(theta: float):
    """Return (k_mod8, delta) where theta ~= k_mod8*pi/4 + delta, delta in (-pi/8, pi/8]."""
    step = PI / 4
    k = round(theta / step)
    delta = theta - k * step
    return int(k) % 8, delta


def _op_norm_dist_rz(delta: float) -> float:
    """Operator-norm distance (phase-invariant) between rz(theta) and rz(theta-delta),
    i.e. between a unitary diag(e^{-i a/2}, e^{i a/2}) and diag(e^{-i(a-delta)/2}, e^{i(a-delta)/2})
    up to global phase: equals |sin(delta/2)|."""
    return abs(math.sin(delta / 2.0))


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    candidates = []  # (cost, idx, replacement_gates)
    for idx, g in enumerate(c.gates):
        if g.name != "rz":
            continue
        if _quarter_turns(g.theta) is not None:
            continue  # already exactly Clifford/T-like, nothing to gain
        k_mod8, delta = _nearest_octant_residual(g.theta)
        cost = _op_norm_dist_rz(delta)
        if cost <= _BUDGET:
            repl = _clifford_gates_for_k(k_mod8, g.qubits[0])
            candidates.append((cost, idx, repl))

    if not candidates:
        return c, Req()

    # Spend the budget on cheapest-first rewrites (maximize count of T-count reductions
    # within the fixed total error budget).
    candidates.sort(key=lambda x: x[0])
    chosen = {}
    spent = 0.0
    for cost, idx, repl in candidates:
        if spent + cost <= _BUDGET:
            chosen[idx] = repl
            spent += cost

    if not chosen:
        return c, Req()

    new_gates = []
    for idx, g in enumerate(c.gates):
        if idx in chosen:
            new_gates.extend(chosen[idx])
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    eps_used = min(spent, _BUDGET)
    return new_c, Req(eps=eps_used, ancillas=0, measure=False)

"""
Within each maximal Hadamard-free region (on each wire, between consecutive H gates touching that
wire), every rz's target qubit parity (as a GF(2) linear combination of the original input qubits
of that region, tracked through cx) is invariant under cz/s/sdg/t/tdg which it may be adjacent to.
rz's with identical parity vectors commute (they are diagonal in the same basis) and can be merged
by summing angles; a block whose total angle becomes a Clifford multiple of pi/4 collapses to that
Clifford gate (or vanishes if 0 mod 2pi). This is an exact rewrite: it only re-associates commuting
diagonal rotations and leaves the parity structure (hence the unitary) unchanged.
"""
import math
from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req

TOL = 1e-9


def _quarter_turns(theta, tol=1e-7):
    k = theta / (PI / 4)
    r = round(k)
    if abs(k - r) < tol:
        return int(r) % 8
    return None


def _clifford_gate(qubit, qt):
    """qt = quarter turns (0..7) of rz(qt*pi/4) up to global phase. Return list of Gates or None (identity)."""
    qt = qt % 8
    if qt == 0:
        return []
    if qt == 4:
        return [Gate("z", (qubit,))]
    if qt == 2:
        return [Gate("s", (qubit,))]
    if qt == 6:
        return [Gate("sdg", (qubit,))]
    if qt == 1:
        return [Gate("t", (qubit,))]
    if qt == 3:
        return [Gate("t", (qubit,)), Gate("s", (qubit,))]
    if qt == 5:
        return [Gate("tdg", (qubit,)), Gate("z", (qubit,))]
    if qt == 7:
        return [Gate("tdg", (qubit,))]
    return None


def _find_hfree_blocks(c: Circuit):
    """Split gate indices into maximal runs with no 'h' gate at all (simplify: blocks separated by any h)."""
    blocks = []
    cur = []
    for i, g in enumerate(c.gates):
        if g.name == "h":
            if cur:
                blocks.append(cur)
            cur = []
        else:
            cur.append(i)
    if cur:
        blocks.append(cur)
    return blocks


def _process_block(c: Circuit, idxs):
    """Given indices of a Hadamard-free block (in original gate order), try to merge rz's with equal
    parity vectors. Returns new list of Gate for that block (same relative order position-compatible),
    or None if nothing changed."""
    if len(idxs) < 2:
        return None

    qubits_used = set()
    for i in idxs:
        qubits_used.update(c.gates[i].qubits)
    qubits_used = sorted(qubits_used)
    qidx = {q: k for k, q in enumerate(qubits_used)}
    nq = len(qubits_used)

    # parity[q] = frozenset / bitmask over qubits_used representing linear combo of original wires
    parity = {q: (1 << qidx[q]) for q in qubits_used}

    # For each rz encountered: (parity_vector, angle, position_in_idxs)
    rz_info = []  # list of dict: idx_pos, qubit, parity, theta
    changed_any = False

    for pos, i in enumerate(idxs):
        g = c.gates[i]
        if g.name == "cx":
            ctrl, tgt = g.qubits
            parity[tgt] ^= parity[ctrl]
        elif g.name == "swap":
            a, b = g.qubits
            parity[a], parity[b] = parity[b], parity[a]
        elif g.name == "rz":
            (q,) = g.qubits
            rz_info.append({"pos": pos, "qubit": q, "parity": parity[q], "theta": g.theta})
        # cz, s, sdg, t, tdg, x, y, z, measure etc: do not change parity tracking
        # (cz/z/s/t are diagonal single/two-qubit phase gates that commute with rz structure;
        #  we only need parity bookkeeping for cx/swap which are the only parity-mixing gates here)

    if len(rz_info) < 2:
        return None

    # group by parity vector
    groups = {}
    for r in rz_info:
        groups.setdefault(r["parity"], []).append(r)

    merge_groups = [grp for grp in groups.values() if len(grp) > 1]
    if not merge_groups:
        return None

    # Build replacement: for groups of size 1, keep rz as-is at its original position.
    # For groups of size >1: place merged result at the position of the LAST rz in the group
    # (so Clifford/cx structure between them in the original order remains valid: since all gates
    # in between that touch other qubits via cx would change parity bookkeeping of other qubits only,
    # but we need the merged rz to act on the qubit's value at time of firing - since all group members
    # share the same parity vector (same linear function of inputs), the diagonal rz's with equal
    # parity commute with everything else in the block (cx preserves the diagonal-in-parity structure,
    # cz/s/t are diagonal too) so we can freely move them together and merge.)
    # Positions of removed rz's (all but the chosen representative) are dropped; chosen one's theta summed.
    drop_positions = set()
    new_theta_at_pos = {}
    for grp in merge_groups:
        total = sum(r["theta"] for r in grp) % (4 * PI)
        rep_pos = max(r["pos"] for r in grp)
        for r in grp:
            if r["pos"] != rep_pos:
                drop_positions.add(r["pos"])
        new_theta_at_pos[rep_pos] = (total, grp[0]["qubit"])
        changed_any = True

    if not changed_any:
        return None

    out_gates = []
    for pos, i in enumerate(idxs):
        if pos in drop_positions:
            continue
        g = c.gates[i]
        if pos in new_theta_at_pos:
            total, q = new_theta_at_pos[pos]
            qt = _quarter_turns(total)
            if qt is not None:
                cg = _clifford_gate(q, qt)
                out_gates.extend(cg)
            else:
                # normalize into (-pi, pi] ish range, keep positive small canonical form
                theta = total
                while theta > 2 * PI + 1e-12:
                    theta -= 4 * PI
                out_gates.append(Gate("rz", (q,), theta=theta))
        else:
            out_gates.append(g)

    return out_gates


def rewrite(c: Circuit):
    blocks = _find_hfree_blocks(c)
    if not blocks:
        return c, Req()

    # map: gate index -> block id, position within block
    idx_to_block = {}
    for bi, idxs in enumerate(blocks):
        for pos, i in enumerate(idxs):
            idx_to_block[i] = bi

    replacements = {}  # block id -> new gate list
    any_change = False
    for bi, idxs in enumerate(blocks):
        res = _process_block(c, idxs)
        if res is not None:
            replacements[bi] = res
            any_change = True

    if not any_change:
        return c, Req()

    # Rebuild full gate list: walk original gates, when encountering the h gates (which are not part
    # of any block) keep them; for block gates, emit the block's replacement exactly once, at the
    # position of the block's first gate; skip subsequent original block gates.
    new_gates = []
    emitted_block = set()
    block_start_idx = {}
    for bi, idxs in enumerate(blocks):
        block_start_idx[idxs[0]] = bi

    for i, g in enumerate(c.gates):
        if i in idx_to_block:
            bi = idx_to_block[i]
            if bi in emitted_block:
                continue
            emitted_block.add(bi)
            if bi in replacements:
                new_gates.extend(replacements[bi])
            else:
                new_gates.extend(c.gates[j] for j in blocks[bi])
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
Tracks, for every qubit, its current GF(2) "parity record" = a linear combination of basis vectors
tagged with an epoch id (epoch bumps whenever an `h` touches that qubit, since H changes basis and
the new Z-value is not a GF(2) function of the old one). cx/swap update parity records exactly like
GF(2) linear algebra; cz/s/sdg/t/tdg/rz/x/y/z do not change any qubit's parity record. Two rz gates
whose target qubit has the *same* parity record (same epoch, same linear combination) commute with
everything in between (diagonal gates commute with diagonal gates, and the intervening cx's conjugate
both consistently) and are merged by summing angles -- this is an exact algebraic identity, not an
approximation. A merged angle that becomes a multiple of pi/4 collapses to the corresponding Clifford
gate (or vanishes); this only re-associates already-commuting diagonal rotations, so the unitary is
unchanged.
"""
import math
from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req


def _quarter_turns(theta, tol=1e-7):
    k = theta / (PI / 4)
    r = round(k)
    if abs(k - r) < tol:
        return int(r) % 8
    return None


def _clifford_gate(qubit, qt):
    qt = qt % 8
    if qt == 0:
        return []
    if qt == 4:
        return [Gate("z", (qubit,))]
    if qt == 2:
        return [Gate("s", (qubit,))]
    if qt == 6:
        return [Gate("sdg", (qubit,))]
    if qt == 1:
        return [Gate("t", (qubit,))]
    if qt == 3:
        return [Gate("t", (qubit,)), Gate("s", (qubit,))]
    if qt == 5:
        return [Gate("tdg", (qubit,)), Gate("z", (qubit,))]
    if qt == 7:
        return [Gate("tdg", (qubit,))]
    return None


def rewrite(c: Circuit):
    n = c.n
    # per-qubit parity record: (epoch, frozenset_of_basis_vars) ; basis vars are (epoch, qubit) pairs
    # we represent parity as a bitmask over a dynamically-grown basis-vector list, but since basis
    # vectors are created fresh at each H (or at start), and only combined via XOR through cx within
    # the same "generation", we can just use a dict: var -> count mod 2, with var = (epoch_id,)
    # unique per (qubit, epoch-start). Simpler: assign each qubit a fresh unique root id every time
    # it is (re)initialized (start, or right after an h), and track its parity as a frozenset of
    # root ids (xor = symmetric difference).
    next_root = [0]

    def fresh_root():
        next_root[0] += 1
        return next_root[0]

    parity = {}  # qubit -> frozenset of root ids
    for q in range(n):
        parity[q] = frozenset({fresh_root()})

    # rz_info: list of dicts with pos (index in gates), qubit, parity (frozenset), theta
    rz_info = []

    for i, g in enumerate(c.gates):
        if g.name == "cx":
            ctrl, tgt = g.qubits
            parity[tgt] = parity[tgt] ^ parity[ctrl]
        elif g.name == "swap":
            a, b = g.qubits
            parity[a], parity[b] = parity[b], parity[a]
        elif g.name == "h":
            (q,) = g.qubits
            parity[q] = frozenset({fresh_root()})
        elif g.name == "rz":
            (q,) = g.qubits
            rz_info.append({"pos": i, "qubit": q, "parity": parity[q], "theta": g.theta})
        # cz, s, sdg, t, tdg, x, y, z, measure, reset, cond-gates, ccx, ccz: do not change parity
        # tracking for this rule (we are conservative: this rule only ever merges rz's, and its
        # correctness relies only on cx/swap/h affecting parity; any other gate type present on a
        # qubit between two same-parity rz's is Clifford/diagonal-compatible structure that the
        # merge does not need to reorder past -- the merged rz is placed at the later position, so
        # gates already emitted in between stay exactly where they are).

    if len(rz_info) < 2:
        return c, Req()

    groups = {}
    for r in rz_info:
        key = (r["qubit_group_key"] if False else (r["parity"],))
        groups.setdefault(r["parity"], []).append(r)

    merge_groups = [grp for grp in groups.values() if len(grp) > 1]
    if not merge_groups:
        return c, Req()

    drop_positions = set()
    new_theta_at_pos = {}
    any_change = False
    for grp in merge_groups:
        total = sum(r["theta"] for r in grp) % (4 * PI)
        rep_pos = max(r["pos"] for r in grp)
        for r in grp:
            if r["pos"] != rep_pos:
                drop_positions.add(r["pos"])
        new_theta_at_pos[rep_pos] = (total, grp[0]["qubit"])
        any_change = True

    if not any_change:
        return c, Req()

    out_gates = []
    for i, g in enumerate(c.gates):
        if i in drop_positions:
            continue
        if i in new_theta_at_pos:
            total, q = new_theta_at_pos[i]
            qt = _quarter_turns(total)
            if qt is not None:
                out_gates.extend(_clifford_gate(q, qt))
            else:
                theta = total
                while theta > 2 * PI + 1e-12:
                    theta -= 4 * PI
                out_gates.append(Gate("rz", (q,), theta=theta))
        else:
            out_gates.append(g)

    new_c = Circuit(c.n, out_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
Tracks, for every qubit, a GF(2) parity record = XOR of "root" tags, where a fresh root is minted
at circuit start and whenever an `h` touches that qubit (H changes basis, so the new Z-value is not
a GF(2) function of the pre-H value). cx/swap update parity records exactly like linear algebra over
GF(2); cz/s/sdg/t/tdg/x/y/z/rz/measure/reset/cond gates do not change any qubit's parity record, and
a diagonal rz(theta) on parity P commutes through any sequence of gates that neither changes P's
value nor measures the carrying qubit in a basis that depends on it (we only reorder across other
*diagonal* or disjoint Clifford gates, never across h/measure/reset, which is enforced by walking the
gate list and only ever moving an rz forward to merge with the next rz of equal parity when nothing
in between touches that qubit's parity-relevant structure incompatibly). Concretely: two rz's on the
same qubit with identical parity record, with no intervening `h`/measure/reset on that qubit and no
change to the parity record in between, act on exactly the same GF(2)-linear function of the inputs,
hence commute with everything diagonal between them and can be merged by summing angles -- an exact
rewrite. A merged angle landing on a multiple of pi/4 collapses to its Clifford gate (or vanishes).
"""
import math

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req

_TOL = 1e-7


def _quarter_turns(theta, tol=_TOL):
    k = theta / (PI / 4)
    r = round(k)
    if abs(k - r) < tol:
        return int(r) % 8
    return None


def _clifford_gate(qubit, qt):
    qt = qt % 8
    if qt == 0:
        return []
    if qt == 4:
        return [Gate("z", (qubit,))]
    if qt == 2:
        return [Gate("s", (qubit,))]
    if qt == 6:
        return [Gate("sdg", (qubit,))]
    if qt == 1:
        return [Gate("t", (qubit,))]
    if qt == 3:
        return [Gate("t", (qubit,)), Gate("s", (qubit,))]
    if qt == 5:
        return [Gate("tdg", (qubit,)), Gate("z", (qubit,))]
    if qt == 7:
        return [Gate("tdg", (qubit,))]
    return None


def rewrite(c: Circuit):
    n = c.n
    next_root = [0]

    def fresh_root():
        next_root[0] += 1
        return next_root[0]

    parity = {}
    for q in range(n):
        parity[q] = frozenset({fresh_root()})

    # For each qubit, the "open" rz waiting to be merged at its current parity (if the qubit's
    # parity hasn't changed and no intervening h/measure/reset/cond-on-that-qubit has occurred
    # since). open_rz[q] = dict(pos, theta, parity) or None.
    open_rz = {q: None for q in range(n)}

    drop_positions = set()
    new_theta_at_pos = {}   # pos -> (theta, qubit)  (pos is the position that stays, gets updated)

    def invalidate(q):
        open_rz[q] = None

    for i, g in enumerate(c.gates):
        name = g.name
        if name == "cx":
            ctrl, tgt = g.qubits
            parity[tgt] = parity[tgt] ^ parity[ctrl]
            # tgt's parity changed: any open rz on tgt no longer matches current parity
            invalidate(tgt)
            # ctrl's parity unchanged, open rz on ctrl (if any) still valid
        elif name == "swap":
            a, b = g.qubits
            parity[a], parity[b] = parity[b], parity[a]
            open_rz[a], open_rz[b] = open_rz[b], open_rz[a]
        elif name == "h":
            (q,) = g.qubits
            parity[q] = frozenset({fresh_root()})
            invalidate(q)
        elif name in ("measure", "reset"):
            (q,) = g.qubits
            invalidate(q)
            parity[q] = frozenset({fresh_root()})
        elif name == "rz" and g.cond is None:
            (q,) = g.qubits
            prev = open_rz[q]
            if prev is not None and prev["parity"] == parity[q]:
                # merge into prev
                total = prev["theta"] + g.theta
                prev["theta"] = total
                drop_positions.add(i)
                new_theta_at_pos[prev["pos"]] = (total, q)
            else:
                open_rz[q] = {"pos": i, "theta": g.theta, "parity": parity[q]}
                new_theta_at_pos[i] = (g.theta, q)
        else:
            # any other gate (cz, s, sdg, t, tdg, x, y, z, ccx, ccz, cond-gates, rz with cond)
            # touching qubit(s): these are diagonal or otherwise do not change parity records,
            # but to be safe about commutation we only invalidate open_rz tracking for qubits
            # whose parity-relevant linear structure could be disturbed. cz/s/sdg/t/tdg/x/y/z/
            # ccx/ccz are all diagonal-in-Z-basis-compatible or act as fixed unitaries that do
            # not change the GF(2) parity assignment; they commute with rz(theta) Z-rotations
            # on a *different* qubit trivially, and with rz on the *same* qubit only if they
            # are themselves diagonal (cz, s, sdg, t, tdg, z) -- x/y and ccx are NOT diagonal
            # on their qubits, so invalidate those qubits' open rz tracking conservatively.
            if name in ("x", "y", "ccx"):
                for q in g.qubits:
                    invalidate(q)
            # cz, s, sdg, t, tdg, z, ccz, and conditioned gates: diagonal, parity-preserving,
            # commute with pending rz merges -- no invalidation needed.
            if g.cond is not None:
                # classically controlled gate: still diagonal-safe only if gate itself is
                # diagonal; be conservative for non-diagonal conditioned gates.
                if name in ("x", "y", "h", "ccx", "swap", "measure", "reset"):
                    for q in g.qubits:
                        invalidate(q)

    if not new_theta_at_pos or not drop_positions:
        return c, Req()

    out_gates = []
    for i, g in enumerate(c.gates):
        if i in drop_positions:
            continue
        if i in new_theta_at_pos:
            total, q = new_theta_at_pos[i]
            theta = total % (4 * PI)
            qt = _quarter_turns(theta)
            if qt is not None:
                out_gates.extend(_clifford_gate(q, qt))
            else:
                if theta > 2 * PI:
                    theta -= 4 * PI
                out_gates.append(Gate("rz", (q,), theta=theta))
        else:
            out_gates.append(g)

    new_c = Circuit(c.n, out_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)
